cpp.setup:
auto* trigger = new fluent::basicinput::Button(QStringLiteral("Show ContentDialog"), %PARENT%);
trigger->setFluentStyle(fluent::basicinput::Button::Accent);
trigger->setFixedSize(168, 32);
trigger->move(136, 119);
trigger->show();
auto* control = new fluent::dialogs_flyouts::ContentDialog(%PARENT%);
control->setAnimationEnabled(false);
control->setTitle(QStringLiteral("Save changes?"));
auto* body = new fluent::textfields::Label(QStringLiteral("Save your edits to \"Release Notes.md\" before closing this document?"), control);
body->setWordWrap(true);
body->setTextColorRole(fluent::textfields::Label::TextColorRole::Secondary);
control->setContent(body);
control->setPrimaryButtonText(QStringLiteral("Save"));
control->setSecondaryButtonText(QStringLiteral("Don't save"));
control->setCloseButtonText(QStringLiteral("Cancel"));
control->setDefaultButton(fluent::dialogs_flyouts::ContentDialog::Primary);
QObject::connect(trigger, &fluent::basicinput::Button::clicked, control, &fluent::dialogs_flyouts::ContentDialog::open);
control->open();
